public class Vehicle {
    private String brand;
    private String model;
    private int    year;
    private double speed;
    private static int    totalVehicles = 0;
    public  static final double MAX_SPEED = 300.0;
    public Vehicle(String brand, String model, int year) {
        if (brand == null || brand.isBlank()) throw new IllegalArgumentException("Brand required");
        this.brand = brand; this.model = model; this.year = year;
        this.speed = 0.0;
        totalVehicles++;
    }
    public void accelerate(double amount) {
        if (amount < 0) throw new IllegalArgumentException("Amount must be positive");
        speed = Math.min(speed + amount, MAX_SPEED);
        System.out.printf("%s %s speed: %.1f km/h%n", brand, model, speed);
    }
    public static int getTotalVehicles() { return totalVehicles; }
    public double getSpeed() { return speed; }
    @Override public String toString() { return brand + " " + model + " (" + year + ")"; }
}

