public class BankAccount {
    private String owner;
    private double balance;
    private String accountType;
    private static final double MIN_BALANCE = 0.0;
    public BankAccount(String owner, double initialBalance, String accountType) {
        setOwner(owner); setBalance(initialBalance);
        this.accountType = accountType != null ? accountType : "Savings";
    }
    public String getOwner()      { return owner;       }
    public double getBalance()    { return balance;     }
    public String getAccountType(){ return accountType; }
    public void setOwner(String owner) {
        if (owner == null || owner.isBlank()) throw new IllegalArgumentException("Owner required");
        this.owner = owner.trim();
    }
    public void setBalance(double balance) {
        if (balance < MIN_BALANCE) throw new IllegalArgumentException("Balance cannot be negative");
        this.balance = balance;
    }
    public void deposit(double amount) {
        if (amount <= 0) throw new IllegalArgumentException("Deposit must be positive");
        balance += amount;
    }
    @Override public String toString() { return String.format("BankAccount{owner='%s', balance=₹%.2f, type='%s'}", owner, balance, accountType); }
}

