public class Temperature {
    public  static final double ABSOLUTE_ZERO_CELSIUS = -273.15;
    private final double celsius;
    public Temperature(double celsius) {
        if (celsius < ABSOLUTE_ZERO_CELSIUS)
            throw new IllegalArgumentException("Temperature below absolute zero: " + celsius);
        this.celsius = celsius;
    }
    public static Temperature fromFahrenheit(double fahrenheit) {
        return new Temperature((fahrenheit - 32) * 5.0 / 9.0);
    }
    public static Temperature fromKelvin(double kelvin) {
        return new Temperature(kelvin - 273.15);
    }
    public double getCelsius()    { return celsius; }
    public double getFahrenheit() { return celsius * 9.0 / 5.0 + 32; }
    public double getKelvin()     { return celsius + 273.15; }
    @Override public String toString() {
        return String.format("%.2f°C / %.2f°F / %.2fK", celsius, getFahrenheit(), getKelvin());
    }
    public static void main(String[] args) {
        Temperature t1 = new Temperature(100);
        Temperature t2 = Temperature.fromFahrenheit(98.6);
        System.out.println(t1); // 100.00°C / 212.00°F / 373.15K
        System.out.println(t2); // 37.00°C / 98.60°F / 310.15K
    }
}

