    private final String state;
    private final String pinCode;
    // constructor, getters, equals, hashCode, toString...
}

items.a:
public record Address(String street, String city, String state, String pinCode) {
    Address {
        if (street  == null || street.isBlank())  throw new IllegalArgumentException("Street required");
        if (city    == null || city.isBlank())    throw new IllegalArgumentException("City required");
        if (state   == null || state.isBlank())   throw new IllegalArgumentException("State required");
        if (pinCode == null || !pinCode.matches("\\d{6}"))
            throw new IllegalArgumentException("PIN code must be 6 digits");
        street  = street.trim();
        city    = city.trim();
        state   = state.trim().toUpperCase();
    }
    public String fullAddress() {
        return street + ", " + city + ", " + state + " - " + pinCode;
    }
}
// Usage:
Address a = new Address("42 MG Road", "Bangalore", "Karnataka", "560001");
System.out.println(a.fullAddress()); // 42 MG Road, Bangalore, KARNATAKA - 560001
System.out.println(a); // auto toString: Address[street=42 MG Road, city=Bangalore, ...]
